def min_extra_char(s, dictionary):
    words = set(dictionary)

    def best(i):
        if i == len(s):
            return 0
        result = 1 + best(i + 1)
        for j in range(i + 1, len(s) + 1):
            if s[i:j] in words:
                result = min(result, best(j))
        return result

    return best(0)

def min_extra_char(s, dictionary):
    words, n = set(dictionary), len(s)
    dp = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        dp[i] = 1 + dp[i + 1]
        for j in range(i + 1, n + 1):
            if s[i:j] in words:
                dp[i] = min(dp[i], dp[j])
    return dp[0]

def min_extra_char(s, dictionary):
    root = {}
    for w in dictionary:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = True
    n = len(s)
    dp = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        dp[i] = 1 + dp[i + 1]
        node = root
        for j in range(i, n):
            node = node.get(s[j])
            if node is None:
                break                            # no word continues this way
            if "$" in node:
                dp[i] = min(dp[i], dp[j + 1])
    return dp[0]
